INSERT INTO `acore_string` (`entry`, `content_default`, `locale_ruRU`) VALUES
(15990000, 'Syntax: .classless status\r\nShows your path, abilities and talents, essence, reroll charges and reroll cooldowns.', 'Синтаксис: .classless status\r\nПоказывает выбранный путь, способности и таланты, эссенции, заряды переброса и время их восстановления.'),
(15990001, 'Syntax: .classless mode classless|wildcard\r\nChooses your path. Only before your path locks.', 'Синтаксис: .classless mode classless|wildcard\r\nВыбирает путь. Доступно только до закрепления пути.'),
(15990002, 'Syntax: .classless learn $spellId\r\nBuys an ability with Ability Essence. Classless path only.', 'Синтаксис: .classless learn $spellId\r\nПокупает способность за эссенцию способностей. Только для свободного пути.'),
(15990003, 'Syntax: .classless unlearn $spellId\r\nUnlearns an ability and refunds its Ability Essence. Classless path only.', 'Синтаксис: .classless unlearn $spellId\r\nЗабывает способность и возвращает эссенцию способностей. Только для свободного пути.'),
(15990004, 'Syntax: .classless talent $talentId\r\nBuys the next rank of a talent with Talent Essence. Classless path only.', 'Синтаксис: .classless talent $talentId\r\nПокупает следующий ранг таланта за эссенцию талантов. Только для свободного пути.'),
(15990005, 'Syntax: .classless respec\r\nUnlearns every ability and talent and refunds all essence. Free. Classless path only.', 'Синтаксис: .classless respec\r\nЗабывает все способности и таланты и возвращает всю эссенцию. Бесплатно. Только для свободного пути.'),
(15990006, 'Syntax: .classless stats\r\nShows your primary stat allocation and unspent points.', 'Синтаксис: .classless stats\r\nПоказывает распределение основных характеристик и нераспределённые очки.'),
(15990007, 'Syntax: .classless stat str|agi|sta|int|spi $points\r\nPuts points into a primary stat. Reallocating is free.', 'Синтаксис: .classless stat str|agi|sta|int|spi $points\r\nРаспределяет очки по основной характеристике. Перераспределение бесплатно.'),
(15990008, 'Syntax: .classless bar mana|rage|energy|default\r\nChooses which resource the main power bar shows.', 'Синтаксис: .classless bar mana|rage|energy|default\r\nВыбирает ресурс для основной шкалы.'),
(15990009, 'Syntax: .classless archetypes\r\nLists the archetypes and their IDs.', 'Синтаксис: .classless archetypes\r\nПоказывает список архетипов и их идентификаторы.'),
(15990010, 'Syntax: .classless archetype $id\r\nFollows an archetype, replacing your build. 0 stops following. Classless path only.', 'Синтаксис: .classless archetype $id\r\nВыбирает архетип вместо вашей сборки. Значение 0 прекращает следование. Только для свободного пути.'),
(15990011, 'Syntax: .classless rebirth [$abilityId ...] confirm\r\nAt the level cap: back to level 1 on your path with a permanent Rebirth rank, carrying the listed heirloom abilities. Without confirm, shows what it will do.', 'Синтаксис: .classless rebirth [$abilityId ...] confirm\r\nНа максимальном уровне возвращает вас на 1-й уровень с постоянным рангом Перерождения и указанными унаследованными способностями. Без confirm показывает результат.'),
(15990012, 'Syntax: .classless challenges\r\nLists the challenge runs with their IDs, lives and rewards.', 'Синтаксис: .classless challenges\r\nПоказывает испытания, их идентификаторы, количество жизней и награды.'),
(15990013, 'Syntax: .classless run $id\r\nStarts a challenge run on a new character, before its path is locked in. .classless challenges lists the IDs.', 'Синтаксис: .classless run $id\r\nНачинает испытание для нового персонажа до выбора пути. Идентификаторы указаны в .classless challenges.'),
(15990014, 'Syntax: .classless nemesis\r\nShows your Nemesis and the available actions for the current challenge run.', 'Синтаксис: .classless nemesis\r\nПоказывает сведения о Немезиде и доступные действия текущего испытания.'),
(15990015, 'Syntax: .wildcard status\r\nShows your path, abilities and talents, reroll charges, synergy chance and reroll cooldowns.', 'Синтаксис: .wildcard status\r\nПоказывает выбранный путь, способности и таланты, заряды переброса, шанс синергии и время восстановления переброса.'),
(15990016, 'Syntax: .wildcard reroll $spellId\r\nRerolls an ability you own. Free below the free-reroll level, then a reroll charge or a Reroll Scroll.', 'Синтаксис: .wildcard reroll $spellId\r\nПеребрасывает изученную способность. Ниже уровня бесплатного переброса это бесплатно, затем расходуется заряд или свиток переброса.'),
(15990017, 'Syntax: .wildcard rerolltalent $talentId [$scrolls]\r\nRerolls a talent you own. Each staked scroll adds a chance to keep the talent and raise its rank instead.', 'Синтаксис: .wildcard rerolltalent $talentId [$scrolls]\r\nПеребрасывает изученный талант. Каждый поставленный свиток повышает шанс сохранить талант и увеличить его ранг.'),
(15990018, 'Syntax: .wildcard lock $spellId\r\nPadlocks or unlocks an ability in your Starting Hand.', 'Синтаксис: .wildcard lock $spellId\r\nЗакрепляет или открепляет способность в стартовой руке.');
